 // pickups
 for(const o of orbs){let x=o.x+ox,y=o.y+oy;ctx.shadowColor='#b9ffcf';ctx.shadowBlur=14;ctx.fillStyle='#c7f5bd';ctx.beginPath();ctx.arc(x,y,o.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f9ffd9';ctx.beginPath();ctx.arc(x-1.5,y-1.5,2,0,Math.PI*2);ctx.fill()}
