 for(const e of enemies){let x=e.x+ox,y=e.y+oy;ctx.save();ctx.translate(x,y);let col=e.type==='wisp'?'#ffcd83':e.type==='brute'?'#769c75':e.type==='boss'?'#a25379':'#82c28e';ctx.shadowColor=col;ctx.shadowBlur=e.type==='boss'?24:12;ctx.fillStyle=e.hit>0?'#fff5d8':col;ctx.beginPath();if(e.type==='boss'){ctx.ellipse(0,0,e.r,e.r*.85,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#f7b2c7';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,e.r+7,frame*.7,frame*.7+Math.PI*1.2);ctx.stroke()}else if(e.type==='wisp'){ctx.moveTo(0,-e.r);ctx.quadraticCurveTo(e.r*1.2,0,0,e.r);ctx.quadraticCurveTo(-e.r*1.2,0,0,-e.r);ctx.fill()}else{ctx.ellipse(0,2,e.r,e.r*.78,0,Math.PI,Math.PI*2);ctx.lineTo(e.r,-2);ctx.quadraticCurveTo(0,e.r*1.5,-e.r,-2);ctx.fill()}ctx.shadowBlur=0;ctx.fillStyle='#20312e';ctx.beginPath();ctx.arc(-e.r*.35,-2,2,0,7);ctx.arc(e.r*.35,-2,2,0,7);ctx.fill();if(e.type==='boss'||e.hp<e.max){ctx.fillStyle='#15231f';rounded(-e.r,-e.r-11,e.r*2,4,3);ctx.fill();ctx.fillStyle='#f5b0a5';rounded(-e.r,-e.r-11,e.r*2*clamp(e.hp/e.max,0,1),4,3);ctx.fill()}ctx.restore()}
