function openShop(){state='shop';renderShop();show(ui.shop)}
function renderShop(){const list=document.getElementById('shopItems');list.innerHTML='';const things=[['vitality','Heartwood charm','+12 starting heart',12],['tempo','Swift-step anklet','+3% movement speed',14],['magnet','Moth-glass locket','+35 mote pickup range',10]];for(let [id,name,desc,cost] of things){let row=document.createElement('div');row.className='shoprow';let label=document.createElement('span');label.innerHTML=`<b style="color:#eff1dc">${name}</b><br><small style="color:#93aa9e">${desc} · owned ${meta[id]||0}</small>`;let b=document.createElement('button');b.textContent=`✧ ${cost}`;b.disabled=shards<cost;b.style.opacity=b.disabled?'.45':'1';b.onclick=()=>{if(shards<cost)return;shards-=cost;meta[id]=(meta[id]||0)+1;localStorage.setItem('fenShards',shards);localStorage.setItem('fenKeepsakes',JSON.stringify(meta));updateHud();renderShop();toast('Keepsake added to your journal')};row.append(label,b);list.appendChild(row)}}
function loop(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;if(state==='run')update(dt);draw();requestAnimationFrame(loop)}
document.getElementById('play').addEventListener('click',start);document.getElementById('again').addEventListener('click',start);document.getElementById('openShop').addEventListener('click',openShop);document.getElementById('closeShop').addEventListener('click',()=>{show(ui.home);state='home'});document.getElementById('pause').addEventListener('click',()=>{if(state==='run'){state='pause';show(ui.pause)}});document.getElementById('resume').addEventListener('click',()=>{state='run';show(null);last=performance.now()});document.getElementById('quit').addEventListener('click',()=>{state='home';ui.hud.style.display='none';ui.ability.style.display='none';ui.xp.style.display='none';document.getElementById('moveHint').style.display='none';show(ui.home)});document.getElementById('endHome').addEventListener('click',()=>{state='home';show(ui.home)});document.getElementById('rift').addEventListener('click',riftstep);
addEventListener('keydown',e=>{keys[e.key]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key===' '||e.key==='Shift')riftstep();if(e.key==='Escape'&&state==='run'){state='pause';show(ui.pause)}else if(e.key==='Escape'&&state==='pause'){state='run';show(null);last=performance.now()}});addEventListener('keyup',e=>keys[e.key]=false);
canvas.addEventListener('pointerdown',e=>{if(state!=='run')return;canvas.setPointerCapture(e.pointerId);pointer={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0}});canvas.addEventListener('pointermove',e=>{if(pointer&&pointer.id===e.pointerId){pointer.dx=clamp((e.clientX-pointer.x)/42,-1,1);pointer.dy=clamp((e.clientY-pointer.y)/42,-1,1)}});function release(e){if(pointer&&pointer.id===e.pointerId)pointer=null}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
updateHud();show(ui.home);last=performance.now();requestAnimationFrame(loop);
})();
</script>
</body>
</html>

